<?php
/**
 * Výchozí data (seed) + funkce pro jejich vložení.
 * -----------------------------------------------------------------------------
 * Data se vloží AUTOMATICKY při prvním připojení (viz scm_db_init_schema).
 * Vkládá se JEN do prázdných tabulek - živá data na serveru se nikdy nepřepíšou.
 */

declare(strict_types=1);

function scm_seed_data(PDO $db): array
{
    $inserted = ['events' => 0, 'programme' => 0, 'awards' => 0];

    // ---- TERMÍN akce ----
    if ((int)$db->query('SELECT COUNT(*) FROM termin')->fetchColumn() === 0) {
        $db->prepare('INSERT INTO termin (datum_cas) VALUES (?)')->execute(['2025-11-08T18:00']);
    }

    // ---- POZVÁNKA (obrázek) ----
    if ((int)$db->query('SELECT COUNT(*) FROM invitation')->fetchColumn() === 0) {
        $db->prepare('INSERT INTO invitation (image) VALUES (?)')->execute(['images/reservation/invation.png']);
    }

    // ---- STAV VSTUPENEK ----
    if ((int)$db->query('SELECT COUNT(*) FROM reservation_status')->fetchColumn() === 0) {
        $db->prepare('INSERT INTO reservation_status (is_active) VALUES (?)')->execute([0]);
    }

    // ---- PROGRAM galavečera ----
    if ((int)$db->query('SELECT COUNT(*) FROM programme')->fetchColumn() === 0) {
        $rows = [
            ['17:30 otevření sálu', '17:30 open hall'],
            ['18:00 slavnostní zahájení SAFE 25 U5 – U9', '18:00 SAFE 2024 opening ceremony'],
            ['Ocenění hráčů kategorií U5 – U9', 'Category U5 – U9 team awards'],
            ['Vyhlášení nejlepších hráčů U11 – muži/ženy', 'Best players awards U11 – muži/ženy'],
            ['Představení Miners klipu + křest', 'Miners clip premiere + launching ceremony'],
            ['Autogramiáda hostů', 'Guests autograph session'],
            ['Medailonky oceněných hráčů', 'Medallions of awarded players'],
            ['Afterparty', 'Afterparty'],
        ];
        $stmt = $db->prepare('INSERT INTO programme (description_cs, description_en, sort_order) VALUES (?,?,?)');
        foreach ($rows as $i => $r) { $stmt->execute([$r[0], $r[1], $i]); }
        $inserted['programme'] = count($rows);
    }

    // ---- MINULÉ ROČNÍKY ----
    if ((int)$db->query('SELECT COUNT(*) FROM events')->fetchColumn() === 0) {
        $rows = [
            ['<h2>2022</h2>', '<h2>2022</h2>', '<p>Prvn&iacute; a z&aacute;roveň jubilejn&iacute; des&aacute;t&yacute; ročn&iacute;k dř&iacute;ve tradičn&iacute; akce&nbsp;<strong>SAFE!</strong> Na programu byly rozhovory s hosty, oceněn&iacute; hr&aacute;čů a videa ze sez&oacute;ny.</p>', '<p>The first and at the same time the jubilee tenth year of the formerly traditional&nbsp;<strong>SAFE!</strong>&nbsp;The program included Guest interviews, player awards and videos from the season.</p>
<div class="first-gallery">&nbsp;</div>', '', '["images\/events/safe01.jpg","images\/events/safe02.jpg","images\/events/safe03.jpg","images\/events/safe04.jpg"]'],
            ['<h2>2023</h2>', '<h2>2023</h2>', '<p>Posledn&iacute; ročn&iacute;k akce&nbsp;<strong>SAFE</strong>&nbsp;byl neuvěřitelně nabit&yacute;! Na&scaron;e pozv&aacute;n&iacute; přijali n&aacute;sleduj&iacute;c&iacute; host&eacute;:</p>
<ul>
<li><strong>Franti&scaron;ek Bure&scaron;</strong>&nbsp;- statut&aacute;rn&iacute; n&aacute;městek prim&aacute;tora a člen Rady města Kladna</li>
<li><strong>Robert Bezděk</strong>&nbsp;- n&aacute;městek prim&aacute;tora a člen Rady města Kladna</li>
<li><strong>Petr Ditrich</strong>&nbsp;- předseda česk&eacute; baseballov&eacute; asociace</li>
<li><strong>Gabriel Waage</strong>&nbsp;- předseda česk&eacute; softballov&eacute; asociace</li>
<li><strong>Evženie Vot&iacute;nsk&aacute;</strong>&nbsp;- vedouc&iacute; PR a marketingu česk&eacute; baseballov&eacute; asociace</li>
<li><strong>Tom&aacute;&scaron; Duffek</strong>&nbsp;- baseballov&yacute; reprezentant Česk&eacute; republiky</li>
<li><strong>Martin Muž&iacute;k</strong>&nbsp;- baseballov&yacute; reprezentant Česk&eacute; republiky</li>
<li><strong>Filip Proch&aacute;zka</strong>&nbsp;- tren&eacute;r baseballov&eacute; reprezentace ČR U18</li>
<li><strong>Michala Kuchařov&aacute;</strong>&nbsp;- b&yacute;val&aacute; elitn&iacute; softballov&aacute; hr&aacute;čka</li>
<li><strong>Nela Jan&aacute;čkov&aacute;</strong>&nbsp;- softballov&aacute; reprezentantka Česk&eacute; republiky</li>
</ul>
<p>Tak vz&aacute;cn&iacute; host&eacute; nemohli zůstat jen tak sedět, a tak byla uspoř&aacute;d&aacute;na autogrami&aacute;da, kterou děti s &uacute;směvem přiv&iacute;taly. Nechybělo ani focen&iacute;.</p>', '<p>The last year of the event&nbsp;<strong>SAFE</strong>&nbsp;It was incredibly charged! Our invitation was accepted by the following guests:</p>
<ul>
<li><strong>Franti&scaron;ek Bure&scaron;</strong>&nbsp;- Statutory Deputy Mayor and Member of the Kladno City Council</li>
<li><strong>Robert Bezděk</strong>&nbsp;- Deputy Mayor and Member of the Kladno City Council</li>
<li><strong>Petr Ditrich</strong>&nbsp;- Chairman of the Czech Baseball Association</li>
